using System.Text;
using System.Threading.Tasks;
using Xunit;

namespace Vibranium.Tests;

// N106, N109, N110 (self-fix-y4). vib-self types each part of an expression once, with every variable an earlier part
// of the same expression declares in scope (C#'s scope), and converts a typeless branch to a target type from the
// types that pass recorded. A variable that is in scope but not definitely assigned stays an error (VIB001).
// The rows of N111 are in Round12SelfEarlierDeclarationTests.
public sealed class Round12SelfBranchScopeTests
{
    // Programs the plan's oracle run accepted on Stage-0 and .NET; the expected text is the .NET output.
    [Theory]
    [InlineData("ii-01-init", "Option<int> o = Pick(0);\nlong r = o is Some<int>(var y) ? 1u : (y = -3);\nWriteLine(r);\nstatic Option<int> Pick(int k) => k > 0 ? Some(k) : None;\n", "-3\n")]
    [InlineData("ii-02-assign", "Option<int> o = Pick(0);\nlong r = 0;\nr = o is Some<int>(var y) ? 1u : (y = -3);\nWriteLine(r);\nstatic Option<int> Pick(int k) => k > 0 ? Some(k) : None;\n", "-3\n")]
