// self-fix-y4: more rows of Round12SelfBranchScopeTests (xUnit runs one class's rows serially).
public sealed class Round12SelfBranchScopeTwinTests
{
    // N110 and its class: a later part of an expression uses a variable that an earlier part of the same expression
    // declares (the true arm for the false arm, a receiver for its arguments, a condition, scrutinee or guard for an arm,
    // one argument for the next). Each program prints a value that is wrong if the variable is lost while the later
    // part is typed (`c ? 1.5f : y` is a float only when y is known to be an int, and 16777217 is not a float), or has
    // no target type there, so that losing it is a rejection. The expected text is the .NET output.
    [Theory]
    [InlineData("n110-t01-var", "bool b = false; Option<int> o = Pick(0);\nvar r = b ? GetI(out int y) : (y = 3); WriteLine(r);\nstatic int GetI(out int v) { v = 1; return 2; }\nstatic Option<int> Pick(int k) => k > 0 ? Some(k) : None;\n", "3\n")]
    [InlineData("n110-t02-write", "bool b = false; Option<int> o = Pick(0);\nWriteLine(b ? GetI(out int y) : (y = 3));\nstatic int GetI(out int v) { v = 1; return 2; }\nstatic Option<int> Pick(int k) => k > 0 ? Some(k) : None;\n", "3\n")]
