    public Task Mix_MaxNesting_ChecksWithinTimeBound(string kind, string position, int depth) =>
        Round12SelfNaturalBranchTypeTests.CheckWithinTimeBoundAsync(BuildMix(kind, position, depth), $"mix {kind} in {position} position at depth {depth}");

    private static string MixLevel(string kind, int i, string next)
    {
        char k = kind == "mix" ? "ABCDEFG"[i % 7] : kind == "mix2" ? "KNISU"[i % 5] : kind[0];
        return k switch
        {
            'A' => $"(H.C({next}) ? 1u : -1)",
            'B' => $"k switch {{ 1 when H.C({next}) => 1u, _ => -1 }}",
            'C' => $"k switch {{ 1 => (H.C({next}) ? 1u : -1), _ => 2L }}",
            'D' => $"(flag ? {next} : -1)",
            'E' => $"k switch {{ 1 => {next}, _ => -1 }}",
            'F' => $"(o is Some<int>(var a{i}) && H.C({next}) ? 1u : (a{i} = -1))",
            'K' => $"(H.C((long)({next})) ? 1u : -1)",
            'N' => $"(H.C(new Nd({next}).V) ? 1u : -1)",
            'I' => $"(H.C(a[H.C({next}) ? 1 : 0]) ? 1u : -1)",
            'S' => $"(H.C(kl = ({next})) ? 1u : -1)",
            'U' => $"(H.C(ol.UnwrapOr({next})) ? 1u : -1)",
            _ => $"(o is not Some<int>(var a{i}) || H.C({next}) ? (a{i} = -1) : 1u)",
        };
    }

    internal static string BuildMix(string kind, string position, int depth)
    {
        string e = "(flag ? 1u : -1)";
        for (int i = depth - 1; i >= 0; i--) e = MixLevel(kind, i, e);
        string pre = "Option<int> o = Some(1); bool flag = true;" + (e.Contains("k switch") ? " int k = 1;" : "");
        pre += (e.Contains("a[") ? " Span<long> a = [1, 1];" : "") + (e.Contains("kl =") ? " long kl = 0;" : "") + (e.Contains("ol.") ? " Option<long> ol = Some(1L);" : "");
        var sb = new StringBuilder();
        switch (position)
        {
            case "arg": sb.Append(pre).Append('\n').Append($"WriteLine(H.F({e}));\n"); break;
            case "init": sb.Append(pre).Append('\n').Append($"long r = {e};\nWriteLine(r);\n"); break;
            case "cast": sb.Append(pre).Append('\n').Append($"WriteLine((long)({e}));\n"); break;
            case "write": sb.Append(pre).Append('\n').Append($"WriteLine({e});\n"); break;
            case "pluseq": sb.Append(pre).Append('\n').Append($"var acc = new Acc();\nacc += ({e});\nWriteLine(acc.Sum);\n"); break;
            default: sb.Append($"WriteLine(G(Some(1), true, 1));\nstatic long G(Option<int> o, bool flag, int k)\n{{\n    return {e};\n}}\n"); break;
        }
        sb.Append("static class H\n{\n    public static bool C(long x) => x > 0;\n    public static bool C(double x) => false;\n");
        sb.Append("    public static long F(long x) => x;\n    public static long F(double x) => 7;\n}\n");
        sb.Append("sealed class Acc { public long Sum; [Mut] public void operator +=(long v) { Sum += v; } }\n");
        if (e.Contains("new Nd(")) sb.Append("sealed class Nd(long v) { public long V = v; }\n");
        return sb.ToString();
    }
